  ['booking-form', 'form'], ['room', 'select'], ['title', 'input', 'text'], ['date', 'input', 'date'],
  ['start', 'input', 'time'], ['end', 'input', 'time'], ['book', 'button', 'submit'],
  ['filter-date', 'input', 'date'], ['show-all', 'button', 'button'], ['booking-list', 'ul'],
