  const params = new URLSearchParams(query ?? '');
  if (!params.has('date')) return { status: 200, body: { bookings: sortBookings(state.bookings) } };
  const date = params.get('date');
  if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
  return { status: 200, body: { bookings: sortBookings(state.bookings.filter((b) => b.date === date)) } };
}

function checkContentType(header) {
  const media = isString(header) ? header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '').toLowerCase() : '';
  if (media !== 'application/json') throw new HttpError(415, 'content type must be application/json');
}

function parseBookingInput(body) {
  let data;
  try {
    data = JSON.parse(body.toString('utf8'));
  } catch {
    throw new HttpError(400, 'body must be a JSON object');
  }
  if (!isPlainObject(data)) throw new HttpError(400, 'body must be a JSON object');
  const [room, title, date, start, end] = ['room', 'title', 'date', 'start', 'end'].map((k) => ownValue(data, k));
  if (!isString(room) || !ROOMS.includes(room)) throw new HttpError(400, 'room must be one of Aurora, Borealis, Cosmos');
  if (!isValidTitle(title)) throw new HttpError(400, 'title must be 1 to 80 characters');
  if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
  if (!isValidTime(start)) throw new HttpError(400, 'start must be HH:MM');
  if (!isValidTime(end)) throw new HttpError(400, 'end must be HH:MM');
  if (end <= start) throw new HttpError(400, 'end must be after start');
  return { room, title: title.trim(), date, start, end };
}

function createBooking(store, req, body) {
  checkContentType(req.headers['content-type']);
  if (body.tooLarge) throw new HttpError(413, 'body too large');
  const input = parseBookingInput(body.data);
  const state = store.state;
  const clash = state.bookings.filter((b) => overlaps(b, input))
    .reduce((first, b) => (first === null || b.start < first.start ? b : first), null);
  if (clash) throw new HttpError(409, `room is already booked from ${clash.start} to ${clash.end}`);
  const booking = { id: state.nextId, ...input };
  store.commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
  return { status: 201, body: booking };
}

function deleteBooking(store, id) {
  const state = store.state;
  const found = /^[1-9][0-9]*$/.test(id) && state.bookings.some((b) => String(b.id) === id);
  if (!found) throw new HttpError(404, 'booking not found');
  store.commit({ nextId: state.nextId, bookings: state.bookings.filter((b) => String(b.id) !== id) });
  return { status: 204, body: null };
}

// ---------- HTTP plumbing ----------

function sendJson(res, status, body) {
  if (body === null) {
    res.writeHead(status);
    res.end();
    return;
  }
  const payload = Buffer.from(JSON.stringify(body), 'utf8');
  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': payload.length });
  res.end(payload);
}

function sendStatic(res, pathname) {
  const file = STATIC_FILES[pathname];
  fs.readFile(file.url, (err, data) => {
    if (err) {
      sendJson(res, 500, { error: 'internal error' });
      return;
    }
    res.writeHead(200, { 'Content-Type': file.type, 'Content-Length': data.length });
    res.end(data);
  });
}

// Reads the whole body; keeps at most MAX_BODY bytes and counts every byte received.
function readBody(req, onDone) {
  const chunks = [];
  let received = 0;
  req.on('data', (chunk) => {
    received += chunk.length;
    if (received <= MAX_BODY) chunks.push(chunk);
  });
  req.on('end', () => onDone({ tooLarge: received > MAX_BODY, data: received > MAX_BODY ? null : Buffer.concat(chunks) }));
  req.on('error', () => req.destroy());
}

function dispatch(store, req, res, body) {
  const { path: pathname, query } = splitTarget(req.url);
  const { handler, id } = route(req.method, pathname, ROUTES);
  switch (handler) {
    case 'static': return sendStatic(res, pathname);
    case 'listRooms': return sendJson(res, 200, { rooms: [...ROOMS] });
    case 'listBookings': return send(res, listBookings(store.state, query));
    case 'createBooking': return send(res, createBooking(store, req, body));
    case 'deleteBooking': return send(res, deleteBooking(store, id));
    default: throw new Error('unknown handler');
  }
}

const send = (res, result) => sendJson(res, result.status, result.body);

function handleRequest(store, req, res) {
  readBody(req, (body) => {
    try {
      dispatch(store, req, res, body);
    } catch (err) {
      const status = err instanceof HttpError ? err.status : 500;
      const message = err instanceof HttpError ? err.message : 'internal error';
      if (!res.headersSent) sendJson(res, status, { error: message });
      else res.destroy();
    }
  });
}

/** Holds the in-memory state; commit saves first and only then swaps state. */
function createStore(filePath, initial) {
  let state = initial;
  return {
    get state() { return state; },
    commit(next) {
      saveState(filePath, next);
      state = next;
    },
  };
}

// ---------- startup ----------

function parsePort(raw) {
  if (raw === undefined || raw === '') return 3000;
  if (!/^[0-9]+$/.test(raw)) return null;
  const port = Number(raw);
  return port <= 65535 ? port : null;
}

function main() {
  const port = parsePort(process.env.PORT);
  if (port === null) {
    // Fixed text: echoing the raw value could add line breaks to the one stderr line.
    process.stderr.write('invalid PORT: must be digits 0-9 with a value up to 65535\n');
    process.exitCode = 1;
    return;
  }
  const name = process.env.DATA_FILE || 'bookings.json';
  const filePath = path.resolve(process.cwd(), name);
  const initial = loadState(filePath);
  if (initial === null) {
    process.stderr.write(`cannot read data file ${name}\n`);
    process.exitCode = 1;
    return;
  }
  const store = createStore(filePath, initial);
  const server = http.createServer((req, res) => handleRequest(store, req, res));
  // Only listen failures (e.g. EADDRINUSE) reach here; request errors are handled per request.
  server.once('error', (err) => {
    process.stderr.write(`cannot listen on port ${port}: ${err.code ?? 'error'}\n`);
    process.exit(1);
  });
  server.listen(port, '127.0.0.1', () => {
    process.stdout.write(`listening on http://127.0.0.1:${server.address().port}\n`);
  });
}

main();
// Meeting-room booking server: JSON API, browser page, one JSON data file.
// Node.js built-ins only.
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HOST = '127.0.0.1';
const DEFAULT_PORT = 3000;
const MAX_PORT = 65535;
const MAX_BODY_BYTES = 10000;
const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
const JSON_TYPE = 'application/json; charset=utf-8';
const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
const PAGES = Object.freeze({
  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
});
const DELETE_ROUTE = /^\/api\/bookings\/[^/]+$/;
const ID_PATTERN = /^[1-9][0-9]*$/;
const DATE_PATTERN = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
const TIME_PATTERN = /^([0-9]{2}):([0-9]{2})$/;

const MSG = Object.freeze({
  contentType: 'content type must be application/json',
  tooLarge: 'body too large',
  notObject: 'body must be a JSON object',
  room: 'room must be one of Aurora, Borealis, Cosmos',
  title: 'title must be 1 to 80 characters',
  date: 'date must be a valid YYYY-MM-DD date',
  start: 'start must be HH:MM',
  end: 'end must be HH:MM',
  order: 'end must be after start',
  bookingNotFound: 'booking not found',
  notFound: 'not found',
  method: 'method not allowed',
  internal: 'internal error',
});

/** Thrown for a request that must get a specific error reply. */
class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
  }
}

// ---------- field validation (shared by the API and the data-file check) ----------

const isPlainObject = (value) =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

function isValidDate(value) {
  if (typeof value !== 'string') return false;
  const match = DATE_PATTERN.exec(value);
  if (!match) return false;
  const [year, month, day] = match.slice(1).map(Number);
  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
  const febDays = year % 4 === 0 ? 29 : 28;
  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= monthDays[month - 1];
}

function isValidTime(value) {
  if (typeof value !== 'string') return false;
  const match = TIME_PATTERN.exec(value);
  return match !== null && Number(match[1]) <= 23 && Number(match[2]) <= 59;
}

function isValidTitle(value) {
  if (typeof value !== 'string') return false;
  const { length } = value.trim();
  return length >= 1 && length <= 80;
}

const overlaps = (a, b) =>
  a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;

/** Rules 4-9 on a parsed body; returns the new booking fields or throws HttpError. */
function validateFields(body) {
  if (typeof body.room !== 'string' || !ROOMS.includes(body.room)) throw new HttpError(400, MSG.room);
  if (!isValidTitle(body.title)) throw new HttpError(400, MSG.title);
  if (!isValidDate(body.date)) throw new HttpError(400, MSG.date);
  if (!isValidTime(body.start)) throw new HttpError(400, MSG.start);
  if (!isValidTime(body.end)) throw new HttpError(400, MSG.end);
  if (!(body.end > body.start)) throw new HttpError(400, MSG.order);
  return { room: body.room, title: body.title.trim(), date: body.date, start: body.start, end: body.end };
}

// ---------- data file ----------

const emptyState = () => Object.freeze({ nextId: 1, bookings: Object.freeze([]) });

function isStoredBooking(b) {
  if (!isPlainObject(b)) return false;
  const keys = Object.keys(b);
  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
  return Number.isSafeInteger(b.id) && b.id >= 1 && ROOMS.includes(b.room)
    && isValidTitle(b.title) && b.title === b.title.trim()
    && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.end > b.start;
}

/** Strict check that `data` is exactly the layout this server writes. */
function isValidLayout(data) {
  if (!isPlainObject(data)) return false;
  const keys = Object.keys(data);
  if (keys.length !== 2 || !keys.includes('nextId') || !keys.includes('bookings')) return false;
  const { nextId, bookings } = data;
  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
  if (!bookings.every(isStoredBooking)) return false;
  const ids = new Set(bookings.map((b) => b.id));
  if (ids.size !== bookings.length || bookings.some((b) => b.id >= nextId)) return false;
  return !bookings.some((b, i) => bookings.slice(i + 1).some((other) => overlaps(b, other)));
}

/** Reads the data file once; returns the state or null when it cannot be used. */
function loadState(filePath) {
  let text;
  try {
    text = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    return err.code === 'ENOENT' ? emptyState() : null;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    return null;
  }
  if (!isValidLayout(data)) return null;
  return Object.freeze({ nextId: data.nextId, bookings: Object.freeze(data.bookings.map((b) => Object.freeze({ ...b }))) });
}

/** Writes a temp file beside the data file, then renames it over, so a failed save leaves the old file intact. */
async function saveState(filePath, state) {
  const tempPath = `${filePath}.${process.pid}.tmp`;
  try {
    await fs.promises.writeFile(tempPath, JSON.stringify({ nextId: state.nextId, bookings: state.bookings }));
    await fs.promises.rename(tempPath, filePath);
  } catch (err) {
    await fs.promises.rm(tempPath, { force: true }).catch(() => {}); // best-effort cleanup; the save error below is what matters
    throw err;
  }
}

// ---------- request plumbing ----------

/** Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes but counts every byte received. */
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let kept = 0;
    let total = 0;
    req.on('data', (chunk) => {
      total += chunk.length;
      if (kept <= MAX_BODY_BYTES) {
        chunks.push(chunk);
        kept += chunk.length;
      }
    });
    req.on('end', () => resolve({ buffer: Buffer.concat(chunks), size: total }));
    req.on('error', reject);
    req.on('aborted', () => reject(new Error('request aborted')));
  });
}

function send(res, status, payload) {
  if (status === 204) {
    res.writeHead(204);
    res.end();
    return;
  }
  const body = JSON.stringify(payload);
  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

const sendError = (res, status, message) => send(res, status, { error: message });

function isJsonContentType(header) {
  if (typeof header !== 'string') return false;
  const media = header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '');
  return media.toLowerCase() === 'application/json';
}

function parseObjectBody(buffer) {
  let parsed;
  try {
    parsed = JSON.parse(buffer.toString('utf8'));
  } catch {
    throw new HttpError(400, MSG.notObject);
  }
  if (!isPlainObject(parsed)) throw new HttpError(400, MSG.notObject);
  return parsed;
}

function compareBookings(a, b) {
  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
}

// ---------- application ----------

function createApp(dataFile, initialState) {
  let state = initialState;

  function listBookings(query) {
    const params = new URLSearchParams(query);
    let bookings = state.bookings;
    if (params.has('date')) {
      const date = params.get('date');
      if (!isValidDate(date)) throw new HttpError(400, MSG.date);
      bookings = bookings.filter((b) => b.date === date);
    }
    return { status: 200, payload: { bookings: [...bookings].sort(compareBookings) } };
  }

  async function createBooking(req, body) {
    if (!isJsonContentType(req.headers['content-type'])) throw new HttpError(415, MSG.contentType);
    if (body.size > MAX_BODY_BYTES) throw new HttpError(413, MSG.tooLarge);
    const fields = validateFields(parseObjectBody(body.buffer));
    const clashes = state.bookings.filter((b) => overlaps(b, fields));
    if (clashes.length > 0) {
      const first = clashes.reduce((a, b) => (b.start < a.start ? b : a));
      throw new HttpError(409, `room is already booked from ${first.start} to ${first.end}`);
    }
    const booking = Object.freeze({ id: state.nextId, ...fields });
    await commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
    return { status: 201, payload: booking };
  }

  async function deleteBooking(rawId) {
    const id = ID_PATTERN.test(rawId) && Number.isSafeInteger(Number(rawId)) ? Number(rawId) : NaN;
    if (!state.bookings.some((b) => b.id === id)) throw new HttpError(404, MSG.bookingNotFound);
    await commit({ nextId: state.nextId, bookings: state.bookings.filter((b) => b.id !== id) });
    return { status: 204 };
  }

  /** Saves the candidate state first; memory changes only when the save succeeded. */
  async function commit(candidate) {
    const next = Object.freeze({ nextId: candidate.nextId, bookings: Object.freeze(candidate.bookings) });
    await saveState(dataFile, next);
    state = next;
  }

  return { listBookings, createBooking, deleteBooking };
}

async function servePage(page) {
  const content = await fs.promises.readFile(path.join(PUBLIC_DIR, page.file));
  return { status: 200, page: { type: page.type, content } };
}

function splitTarget(target) {
  const mark = target.indexOf('?');
  return mark === -1
    ? { pathname: target, query: '' }
    : { pathname: target.slice(0, mark), query: target.slice(mark + 1) };
}

function requireMethod(method, allowed) {
  if (method !== allowed) throw new HttpError(405, MSG.method);
}

/** Routes one request (body already read) to its result, or throws HttpError. */
async function route(app, req, body) {
  const { pathname, query } = splitTarget(req.url);
  const { method } = req;
  if (Object.hasOwn(PAGES, pathname)) {
    requireMethod(method, 'GET');
    return servePage(PAGES[pathname]);
  }
  if (pathname === '/api/rooms') {
    requireMethod(method, 'GET');
    return { status: 200, payload: { rooms: [...ROOMS] } };
  }
  if (pathname === '/api/bookings') {
    if (method === 'GET') return app.listBookings(query);
    if (method === 'POST') return app.createBooking(req, body);
    throw new HttpError(405, MSG.method);
  }
  if (DELETE_ROUTE.test(pathname)) {
    requireMethod(method, 'DELETE');
    return app.deleteBooking(pathname.slice('/api/bookings/'.length));
  }
  throw new HttpError(404, MSG.notFound);
}

function writeResult(res, result) {
  if (result.page) {
    res.writeHead(200, { 'Content-Type': result.page.type, 'Content-Length': result.page.content.length });
    res.end(result.page.content);
    return;
  }
  send(res, result.status, result.payload);
}

/** Logs an unexpected failure as one stderr line (stdout is reserved for the listening line). */
function logUnexpected(err) {
  const detail = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
  process.stderr.write(`request failed: ${detail.replace(/\s+/g, ' ')}\n`);
}

function writeFailure(res, err) {
  if (!(err instanceof HttpError)) logUnexpected(err);
  if (res.headersSent) {
    res.destroy();
    return;
  }
  if (err instanceof HttpError) sendError(res, err.status, err.message);
  else sendError(res, 500, MSG.internal);
}

/** Serialises request handling so concurrent requests act as if handled one at a time. */
function createHandler(app) {
  let queue = Promise.resolve();
  return (req, res) => {
    // A failed write to a vanished client must not crash the server; nothing else to do.
    res.on('error', () => {});
    readBody(req).then(
      (body) => {
        queue = queue.then(() => route(app, req, body)
          .then((result) => writeResult(res, result), (err) => writeFailure(res, err))
          .catch((err) => {
            logUnexpected(err);
            res.destroy();
          }));
      },
      () => res.destroy(), // client aborted before sending its body: there is no one to reply to
    );
  };
}

// ---------- startup ----------

function fail(line) {
  process.stderr.write(`${line}\n`);
  process.exit(1);
}

function parsePort(raw) {
  if (raw === undefined || raw === '') return DEFAULT_PORT;
  if (!/^[0-9]+$/.test(raw)) return null;
  const port = Number(raw);
  return port <= MAX_PORT ? port : null;
}

function main() {
  const port = parsePort(process.env.PORT);
  if (port === null) fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
  const dataName = process.env.DATA_FILE || 'bookings.json';
  const dataFile = path.resolve(process.cwd(), dataName);
  const state = loadState(dataFile);
  if (state === null) fail(`cannot read data file ${dataName}`);

  const server = http.createServer(createHandler(createApp(dataFile, state)));
  server.on('clientError', (_err, socket) => {
    if (socket.writable) socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n');
    else socket.destroy();
  });
  const onListenError = (err) => fail(`cannot listen on port ${port}: ${err.code || 'error'}`);
  server.once('error', onListenError);
  server.listen(port, HOST, () => {
    server.off('error', onListenError);
    server.on('error', logUnexpected);
    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
  });
}

main();

  1: # Room bookings
  2: 
  3: A small meeting-room booking app. One Node.js server (`server.mjs`) serves a
  4: JSON API and a browser page, and keeps every booking in a single JSON file.
  5: There are three fixed rooms: `Aurora`, `Borealis` and `Cosmos`.
  6: 
  7: ## Requirements
  8: 
  9: - Node.js 18 or later (the server and tests use only built-in modules).
 10: - No dependencies. Nothing to install: there is no `npm install` step.
 11: 
 12: ## Usage
 13: 
 14: ```sh
 15: npm start            # same as: node server.mjs
 16: ```
 17: 
 18: Once it is listening, the server prints exactly one line to stdout:
 19: 
 20: ```
 21: listening on http://127.0.0.1:3000
 22: ```
 23: 
 24: Open that address in a browser to use the page. The server only listens on
 25: `127.0.0.1`.
 26: 
 27: ### Environment variables
 28: 
 29: | Variable    | Default         | Meaning |
 30: |-------------|-----------------|---------|
 31: | `PORT`      | `3000`          | Port to listen on. Must be ASCII digits only, at most `65535`. `0` lets the OS pick a free port (the printed line shows the real one). Unset or empty means the default. |
 32: | `DATA_FILE` | `bookings.json` | Path of the data file. A relative path, the default included, is resolved against the current working directory, not the folder of `server.mjs`. Unset or empty means the default. |
 33: 
 34: ```sh
 35: PORT=8080 npm start
 36: PORT=0 DATA_FILE=/tmp/rooms.json node server.mjs
 37: DATA_FILE=data/bookings.json node server.mjs   # the data/ folder must already exist
 38: ```
 39: 
 40: ### Startup order and exit codes
 41: 
 42: At startup the server checks `PORT`, then reads the data file, then starts
 43: listening. Any startup failure writes one line to stderr, prints nothing on
 44: stdout, and exits with code `1`:
 45: 
 46: | Cause | stderr line |
 47: |-------|-------------|
 48: | `PORT` is not all digits, or is above 65535 | `invalid PORT "<value>"` |
 49: | The data file exists but cannot be read, or its content is not the layout below (empty, bad JSON, a folder, and so on) | `cannot read data file <DATA_FILE as given>` |
 50: | The port cannot be bound (for example it is in use) | `cannot listen on 127.0.0.1:<port>: <code>` (for example `EADDRINUSE`) |
 51: 
 52: A missing data file (or a missing folder on its path, `ENOENT`) is not an
 53: error: the server starts with no bookings. After startup the server keeps
 54: running until it is stopped; errors while handling requests are logged to
 55: stderr as `server error: <code>` and answered with 500.
 56: 
 57: ## API
 58: 
 59: All JSON replies have `Content-Type: application/json; charset=utf-8`. Every
 60: error reply has the body `{"error": "<message>"}`.
 61: 
 62: Paths are matched byte for byte against the request target up to the first
 63: `?`: no percent-decoding and no slash, dot-segment or case normalisation
 64: (`/API/rooms` and `/api/bookings/` are not valid routes). The query string is
 65: ignored except for `date` on `GET /api/bookings`.
 66: 
 67: | Method and path | Success | Errors |
 68: |-----------------|---------|--------|
 69: | `GET /api/rooms` | 200 `{"rooms": ["Aurora", "Borealis", "Cosmos"]}` | |
 70: | `GET /api/bookings` | 200 `{"bookings": [...]}` | 400 `date must be a valid YYYY-MM-DD date` |
 71: | `POST /api/bookings` | 201, the new booking | 415, 413, 400, 409, 500 (see below) |
 72: | `DELETE /api/bookings/<id>` | 204, empty body | 404 `booking not found`, 500 `internal error` |
 73: | `GET /` | 200, the page (`text/html; charset=utf-8`) | |
 74: | `GET /app.js` | 200, the page script (`text/javascript; charset=utf-8`) | |
 75: 
 76: Errors that apply to every route:
 77: 
 78: - Unknown path, any method: 404 `not found`. This includes `/api/bookings/`
 79:   and any `/api/bookings/...` path whose rest contains a `/`.
 80: - Known path with a method not listed for it (HEAD and OPTIONS included):
 81:   405 `method not allowed`. For example `GET /api/bookings/1` is 405.
 82: - Any unexpected failure, including a failed save: 500 `internal error`.
 83: 
 84: ### Bookings
 85: 
 86: A booking has exactly these keys:
 87: 
 88: ```json
 89: {"id": 1, "room": "Aurora", "title": "Standup", "date": "2026-11-03", "start": "09:00", "end": "10:00"}
 90: ```
 91: 
 92: Ids start at 1 and go up by one. An id is never reused, even after deletes
 93: and restarts.
 94: 
 95: ### `GET /api/bookings`
 96: 
 97: Returns every booking, sorted by date, then start time, then room (in the
 98: order Aurora, Borealis, Cosmos).
 99: 
100: ```sh
101: curl http://127.0.0.1:3000/api/bookings
102: curl 'http://127.0.0.1:3000/api/bookings?date=2026-11-03'
103: ```
104: 
105: With a `date` query parameter, only bookings on that date are returned. The
106: first `date` value counts if it is repeated, and `?date` with no value counts
107: as the empty value. A value that is not a valid date (rule 6 below, the empty
108: value included) gets 400 `date must be a valid YYYY-MM-DD date`.
109: 
110: ### `POST /api/bookings`
111: 
112: ```sh
113: curl -i -X POST http://127.0.0.1:3000/api/bookings \
114:   -H 'Content-Type: application/json' \
115:   -d '{"room":"Aurora","title":"Standup","date":"2026-11-03","start":"09:00","end":"10:00"}'
116: ```
117: 
118: ```
119: HTTP/1.1 201 Created
120: {"id":1,"room":"Aurora","title":"Standup","date":"2026-11-03","start":"09:00","end":"10:00"}
121: ```
122: 
123: Other keys in the body are ignored. The rules are checked in this order, and
124: the first one that fails decides the reply:
125: 
126: | # | Rule | Reply |
127: |---|------|-------|
128: | 1 | The `Content-Type` media type (before the first `;`, spaces and tabs trimmed, case ignored) is `application/json` | 415 `content type must be application/json` |
129: | 2 | The body is at most 10000 bytes | 413 `body too large` |
130: | 3 | The body (decoded as UTF-8) parses as a JSON object, not an array, `null`, a string, number or boolean, and is not empty | 400 `body must be a JSON object` |
131: | 4 | `room` is exactly `Aurora`, `Borealis` or `Cosmos` (case matters) | 400 `room must be one of Aurora, Borealis, Cosmos` |
132: | 5 | `title` is a string of 1 to 80 characters (UTF-16 code units) after trimming whitespace at both ends | 400 `title must be 1 to 80 characters` |
133: | 6 | `date` is `YYYY-MM-DD`, a real day from 2000-01-01 to 2099-12-31 (February has 29 days in years divisible by 4) | 400 `date must be a valid YYYY-MM-DD date` |
134: | 7 | `start` is `HH:MM`, from `00:00` to `23:59` | 400 `start must be HH:MM` |
135: | 8 | `end` is `HH:MM`, from `00:00` to `23:59` | 400 `end must be HH:MM` |
136: | 9 | `end` is later than `start` | 400 `end must be after start` |
137: | 10 | No overlap with a booking of the same room on the same date | 409 `room is already booked from <start> to <end>` |
138: 
139: - Only `title` is trimmed, and the booking stores the trimmed title. No other
140:   field is changed: ` 2026-11-03`, `2026-11-3` and `9:00` are invalid.
141: - Two bookings overlap when each starts before the other ends. A booking may
142:   start exactly when another ends. The 409 message names the start and end of
143:   the overlapping booking that starts earliest, for example
144:   `room is already booked from 09:00 to 10:00`.
145: - Requests that arrive at the same time are handled one at a time: of several
146:   overlapping bookings sent at once, exactly one is created and the others get
147:   409.
148: 
149: ### `DELETE /api/bookings/<id>`
150: 
151: ```sh
152: curl -i -X DELETE http://127.0.0.1:3000/api/bookings/1
153: ```
154: 
155: Replies 204 with an empty body. When `<id>` is not a positive integer in plain
156: digits without a leading zero (for example `abc`, `01`, `-1`), or no booking
157: has that id, the reply is 404 `booking not found`.
158: 
159: ## Data file
160: 
161: The data file holds one JSON object, written compactly with no trailing
162: newline:
163: 
164: ```json
165: {"nextId":3,"bookings":[{"id":1,"room":"Aurora","title":"Standup","date":"2026-11-03","start":"09:00","end":"10:00"}]}
166: ```
167: 
168: - `nextId` is the id the next booking will get. `bookings` is kept in creation
169:   order; the API sorts on read.
170: - The file is read once, at startup. It must be exactly this layout: only the
171:   keys `nextId` and `bookings`; each booking with exactly its six keys and
172:   valid values (title already trimmed, end after start); ids unique, at least
173:   1 and below `nextId`; and no two bookings overlapping. Anything else stops
174:   startup with `cannot read data file <name>`.
175: - After startup, memory is the source of truth. Changes made to the file from
176:   outside are not noticed.
177: - The file is written only when a POST creates a booking or a DELETE removes
178:   one, and the save finishes before the reply is sent, so a restart with the
179:   same `DATA_FILE` keeps the bookings and the next id.
180: - The server never creates folders. If a save fails (for example because the
181:   file's folder does not exist), the reply is 500 `internal error` and nothing
182:   changes, the next id included. The server keeps running.
183: - The file is overwritten in place (no temp file). A write that fails partway,
184:   for example on a full disk, can leave it damaged, and the next startup will
185:   then refuse it.
186: 
187: ## Tests
188: 
189: ```sh
190: npm test             # runs: node --test test/
191: ```
192: 
193: The tests use the built-in `node:test` runner and live in `test/`. To run the
194: server the same way by hand without touching your `bookings.json`, use
195: `PORT=0` and a temporary `DATA_FILE`.
